<template><div class="trend-sparkline"><svg viewBox="0 0 600 156" role="img" :aria-label="'问答趋势：' + data.map(d=>d.date+' '+d.qa_count+'次').join('，')"><defs><linearGradient :id="gradientId" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--color-accent)" stop-opacity=".24"/><stop offset="100%" stop-color="var(--color-accent)" stop-opacity="0"/></linearGradient></defs><path v-for="n in 3" :key="n" :d="'M 15 '+(n*37)+' H 585'" stroke="var(--color-line)" stroke-dasharray="4 4"/><path :d="area" :fill="'url(#' + gradientId + ')'"/><polyline :points="points" fill="none" stroke="var(--color-accent)" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round"/><circle v-for="(p,i) in coordinates" :key="i" :cx="p[0]" :cy="p[1]" r="3" fill="var(--color-surface)" stroke="var(--color-accent)" stroke-width="1.5"><title>{{ data[i]?.date }}：{{ data[i]?.qa_count }} 次问答</title></circle></svg><div class="trend-labels"><span v-for="d in data" :key="d.date">{{ d.date.slice(5).replace('-', '/') }}</span></div></div></template>
<script setup>import { computed, getCurrentInstance } from 'vue'; const props=defineProps({data:{type:Array,default:()=>[]}});const gradientId='trend-fill-'+getCurrentInstance().uid;const max=computed(()=>Math.max(1,...props.data.map(d=>d.qa_count)));const coordinates=computed(()=>props.data.map((d,i)=>[15+i*(570/Math.max(props.data.length-1,1)),125-d.qa_count/max.value*105]));const points=computed(()=>coordinates.value.map(p=>p.join(',')).join(' '));const area=computed(()=>coordinates.value.length?'M '+coordinates.value.map(p=>p.join(' ')).join(' L ')+' L '+coordinates.value.at(-1)[0]+' 140 L 15 140 Z':'')</script><style scoped>.trend-sparkline{padding:14px 4px 4px}.trend-sparkline svg{width:100%;height:156px;display:block;overflow:visible}.trend-labels{display:flex;justify-content:space-between;font-size:12px;color:var(--color-muted);padding:0 13px 0 10px}</style>